ALTER TABLE public.owner_reservations ADD COLUMN guest_user_id uuid;
CREATE INDEX owner_reservations_guest_idx ON public.owner_reservations(guest_user_id);
COMMENT ON COLUMN public.owner_reservations.guest_user_id IS 'Authenticated guest who requested this stay; immutable after creation. Owner-created historical reservations remain NULL.';
CREATE OR REPLACE FUNCTION public.guard_reservation_guest_identity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF new.guest_user_id IS DISTINCT FROM old.guest_user_id THEN RAISE EXCEPTION 'Guest account cannot be reassigned'; END IF; RETURN new; END $$;
CREATE TRIGGER guard_reservation_guest_identity BEFORE UPDATE ON public.owner_reservations FOR EACH ROW EXECUTE FUNCTION public.guard_reservation_guest_identity();
REVOKE ALL ON FUNCTION public.guard_reservation_guest_identity() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.request_partner_stay(_room_id uuid,_check_in date,_check_out date,_guests integer,_name text,_email text,_phone text,_requests text DEFAULT '') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.owner_rooms; rid uuid; day date; booked int; BEGIN
IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Please sign in to request a stay'; END IF;
IF _check_in IS NULL OR _check_out IS NULL OR _check_in<current_date OR _check_out<=_check_in OR _check_out-_check_in>90 THEN RAISE EXCEPTION 'Choose a future stay of 1 to 90 nights'; END IF;
IF _guests IS NULL OR _guests<1 OR _name IS NULL OR length(trim(_name))<2 OR length(_name)>100 OR _email IS NULL OR length(_email)>255 OR _email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR _phone IS NULL OR _phone !~ '^\+?[0-9]{10,15}$' OR length(coalesce(_requests,''))>2000 THEN RAISE EXCEPTION 'Check your guest details'; END IF;
SELECT r0.* INTO r FROM public.owner_rooms r0 JOIN public.owner_properties p ON p.id=r0.property_id JOIN public.business_owners b ON b.user_id=p.owner_id WHERE r0.id=_room_id AND p.status='Approved' AND b.status='Approved' FOR UPDATE OF r0;
IF NOT FOUND OR NOT r.available OR r.units<1 THEN RAISE EXCEPTION 'This room is not open for booking requests'; END IF;
IF _guests>r.capacity THEN RAISE EXCEPTION 'Guest count exceeds room capacity'; END IF;
day:=_check_in; WHILE day<_check_out LOOP SELECT count(*) INTO booked FROM public.owner_reservations x WHERE x.room_id=r.id AND x.status IN ('Confirmed','Checked In') AND x.check_in<=day AND x.check_out>day; IF booked>=r.units THEN RAISE EXCEPTION 'No remaining units for these dates'; END IF; day:=day+1; END LOOP;
INSERT INTO public.owner_reservations(owner_id,property_id,room_id,guest_user_id,guest_name,guest_email,guest_phone,check_in,check_out,guests,amount,status,notes) VALUES(r.owner_id,r.property_id,r.id,auth.uid(),trim(_name),trim(_email),_phone,_check_in,_check_out,_guests,0,'Requested',coalesce(_requests,'')) RETURNING id INTO rid;
RETURN rid; END $$;
REVOKE ALL ON FUNCTION public.request_partner_stay(uuid,date,date,integer,text,text,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.request_partner_stay(uuid,date,date,integer,text,text,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.my_partner_stays() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('id',b.id,'property_name',p.name,'room_name',r.name,'check_in',b.check_in,'check_out',b.check_out,'guests',b.guests,'amount',b.amount,'status',b.status,'created_at',b.created_at) ORDER BY b.created_at DESC),'[]'::jsonb) FROM public.owner_reservations b LEFT JOIN public.owner_properties p ON p.id=b.property_id LEFT JOIN public.owner_rooms r ON r.id=b.room_id WHERE b.guest_user_id=auth.uid() $$;
REVOKE ALL ON FUNCTION public.my_partner_stays() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.my_partner_stays() TO authenticated;
CREATE OR REPLACE FUNCTION public.cancel_partner_stay(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Please sign in'; END IF; UPDATE public.owner_reservations SET status='Cancelled' WHERE id=_id AND guest_user_id=auth.uid() AND status IN ('Requested','Confirmed') AND check_in>=current_date; IF NOT FOUND THEN RAISE EXCEPTION 'This request cannot be cancelled'; END IF; END $$;
REVOKE ALL ON FUNCTION public.cancel_partner_stay(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.cancel_partner_stay(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.public_listings() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'kind',p.kind,'description',p.description,'location',p.location,'amenities',p.amenities,'check_in',p.check_in,'check_out',p.check_out,'photos',p.photos,'rooms',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',r.id,'name',r.name,'room_type',r.room_type,'description',r.description,'capacity',r.capacity,'facilities',r.facilities,'price',r.price,'seasonal_price',r.seasonal_price,'season_start',r.season_start,'season_end',r.season_end,'discount_pct',r.discount_pct,'photos',r.photos,'available',r.available,'units',r.units,'occupied_units',(SELECT count(*) FROM public.owner_reservations x WHERE x.room_id=r.id AND x.status IN ('Confirmed','Checked In') AND x.check_in<=current_date AND x.check_out>current_date)) ORDER BY r.price),'[]'::jsonb) FROM public.owner_rooms r WHERE r.property_id=p.id)) ORDER BY p.updated_at DESC),'[]'::jsonb) FROM public.owner_properties p JOIN public.business_owners b ON b.user_id=p.owner_id WHERE p.status='Approved' AND b.status='Approved' $$;
REVOKE ALL ON FUNCTION public.public_listings() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.public_listings() TO anon,authenticated,service_role;